const job = $input.item.json;

const overall = Math.round((job.overall || 0) * 100);
const verdict = job.verdict || 'CONSIDER';
const emoji = verdict === 'PRIORITY' ? '🔥' : '👀';
const track = job.track || 'UNKNOWN';
const trackLabel = track === 'A' ? '.NET/DevOps' : track === 'B' ? 'WordPress/PHP' : 'Nieznany';

const redFlags = (job.red_flags || []).filter(f => f !== 'none').join(', ') || 'brak';
const greenFlags = (job.green_flags || []).filter(f => f !== 'none').join(', ') || 'brak';

const body = `${emoji} NOWE ZLECENIE [${verdict}] — Score: ${overall}/100
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
📋 OFERTA
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
Portal:  ${job.source_portal || '?'}
Tytuł:   ${job.title || '?'}
Firma:   ${job.company || '?'}
Budżet:  ${job.salary || 'nie podano'}
URL:     ${job.url}
Track:   ${track} (${trackLabel})

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
🤖 ANALIZA AI (Ollama)
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
Score:         ${overall}/100
Tech match:    ${Math.round((job.tech_score || 0) * 100)}/100
Seniority:     ${Math.round((job.seniority_score || 0) * 100)}/100
Project fit:   ${Math.round((job.project_fit || 0) * 100)}/100
Budżet fit:    ${Math.round((job.budget_fit || 0) * 100)}/100
Stawka:        ${job.suggested_rate || 'do negocjacji'}

🚩 Red flags:  ${redFlags}
✅ Green flags: ${greenFlags}
💡 ${job.reasoning || ''}

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
✍️ PROPOZYCJA [BALANCED — rekomendowana]
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
${job.proposal_balanced || 'Propozycja nie została jeszcze wygenerowana.'}

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
📄 AGGRESSIVE
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
${job.proposal_aggressive || '-'}

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
📄 PREMIUM
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
${job.proposal_premium || '-'}

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
ID oferty: ${job.job_id}
Oceniono: ${job.scored_at}`;

return [{ json: {
  subject: `${emoji} [${verdict}] ${job.source_portal}: ${job.title} | ${overall}/100`,
  body,
  score_id: job.score_id,
  job_id: job.job_id,
  verdict
}}];
